 table='\n## Componentes centrais\n\n|Componente|Fonte e símbolo|Comportamento e limite|\n|---|---|---|\n'+'\n'.join(f'|{x[0]}|{ref(x[1],x[2])}|{x[3]}|' for x in d['components'])
